    ////////////////////////////////////////////////////////
    //
    // Main seed loops
    //
    TwistExpander_Altair_Arx::SEED_A(PARAMS_SEED);

    TwistExpander_Altair_Arx::SEED_B(PARAMS_SEED);

    std::uint64_t aDomainWordMatrixSelectA = pWorkSpace->mDomainBundle.mSeedConstants.mMatrixSelectA;
